#!/usr/bin/env node
// Writes one module per entry of ./tesseract-languages.json under modules/tesseract-lang/<code>/,
// then pins every model with `telo release stage --pin`. Generated files are checked
// in; edit the table or this script, never a generated module, and run it again.
//
// Usage: node scripts/generate-tesseract-language-modules.mjs [--no-pin] [--only deu,pol]

import { execFileSync } from "node:child_process";
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, "..");
const tesseractDir = join(repoRoot, "modules", "tesseract");
const tablePath = join(here, "tesseract-languages.json");
const familyDir = join(repoRoot, "modules", "tesseract-lang");
const notice = join(tesseractDir, "notices", "tessdata.LICENSE");
const pin = !process.argv.includes("--no-pin");
const onlyAt = process.argv.indexOf("--only");
const only = onlyAt >= 0 ? new Set(process.argv[onlyAt + 1].split(",")) : undefined;
const languages = JSON.parse(readFileSync(tablePath, "utf8")).filter(
  (lang) => !only || only.has(lang.code),
);

const INITIAL_VERSION = "0.1.0";
// Absolute: each language module is published, and shown on the hub, on its own.
const DOCS = "https://github.com/telorun/telo/blob/main/modules/tesseract/docs";
const TESSDATA_VERSION = "1.0.0";

const pascal = (code) =>
  code
    .split("_")
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join("");

const subject = ({ code, name }) =>
`${name} text`;

const described = ({ name, script }) =>
`printed ${name} (${script} script)`;

function manifest(lang) {
  const { code } = lang;
  const alias = pascal(code);
  return `# Generated by scripts/generate-tesseract-language-modules.mjs from
# scripts/tesseract-languages.json. Edit the table or the script and run it again.
kind: Telo.Library
metadata:
  name: TesseractLang${alias}
  version: ${INITIAL_VERSION}
  repository: https://github.com/telorun/telo
  license: LicenseRef-SustainableUse
  categories: [AI]
  description: |
    Recognize ${subject(lang)} in images, offline: the trained model for reading
    ${described(lang)} with Tesseract optical character recognition.
    Import it and hand its one ready-made model to a recognizer, beside any other
    languages a page mixes. Packaged from the integer-quantized best models of the
    tesseract-ocr project.
requires:
  # 0.100.0: \`!module-path\` naming a \`sources:\`-staged model counts as present,
  # in \`telo check\` and in release planning from pins.
  telo: ">=0.100.0"
imports:
  TesseractModel: ../../tesseract-model
exports:
  resources:
    - ${code}
assets:
  - ./tessdata/
sources:
  # The package carries no notice of its own; the checked-in one is the Apache-2.0
  # notice of tesseract-ocr/tessdata.
  tessdata:
    version: ${TESSDATA_VERSION}
    url: https://registry.npmjs.org/@tesseract.js-data/{upstream}/-/{upstream}-{version}.tgz
    archive: tar.gz
    notices: [./notices/tessdata.LICENSE]
    entries:
      ./tessdata/${code}.traineddata.gz:
        { upstream: ${code}, member: package/4.0.0_best_int/${code}.traineddata.gz }
---
kind: TesseractModel.Language
metadata:
  name: ${code}
  description: ${lang.name}, ${lang.script} script
code: ${code}
data: !module-path ./tessdata/${code}.traineddata.gz
`;
}

function readme(lang) {
  const { code, name } = lang;
  const alias = pascal(code);
  return `# Tesseract ${code}

The Tesseract model for ${name} (${lang.script} script), as one ready-made model a recognizer
references. Generated from \`scripts/tesseract-languages.json\`: edit the table or the
generator, never this module.

## Example

\`\`\`yaml
kind: Telo.Application
metadata:
  name: ReadScans
imports:
  Tesseract: oci://ghcr.io/telorun/tesseract
  ${alias}: oci://ghcr.io/telorun/tesseract-lang/${code}
---
kind: Tesseract.Recognizer
metadata:
  name: recognizer
languages:
  - !ref ${alias}.${code}
  - !ref Tesseract.eng
\`\`\`

The imports carry no version, so they resolve to the latest release; \`telo install\`
pins each one to the version it resolved.

## Documentation

- [Languages and models](${DOCS}/languages.md)
- [Getting started with Tesseract](${DOCS}/getting-started.md)
`;
}

const GITIGNORE = `# Staged from the \`sources:\` pin by \`telo release stage\`, and by the kernel on
# first use in a checkout.
/tessdata/
`;

const written = [];
for (const lang of languages) {
  const dir = join(familyDir, lang.code);
  mkdirSync(join(dir, "notices"), { recursive: true });
  const manifestPath = join(dir, "telo.yaml");
  // Keep a released version and the pin: regenerating must not reset either.
  const previous = existsSync(manifestPath) ? readFileSync(manifestPath, "utf8") : undefined;
  let next = manifest(lang);
  if (previous) {
    const version = previous.match(/^  version: (\S+)$/m)?.[1];
    const pinned = previous.match(/^        \{ upstream: .*\}$/m)?.[0];
    if (version) next = next.replace(/^  version: \S+$/m, `  version: ${version}`);
    if (pinned) next = next.replace(/^        \{ upstream: .*\}$/m, pinned);
  }
  writeFileSync(manifestPath, next);
  writeFileSync(join(dir, "README.md"), readme(lang));
  writeFileSync(join(dir, ".gitignore"), GITIGNORE);
  if (!existsSync(join(dir, "CHANGELOG.md"))) writeFileSync(join(dir, "CHANGELOG.md"), "# Changelog\n");
  copyFileSync(notice, join(dir, "notices", "tessdata.LICENSE"));
  written.push(relative(repoRoot, dir));
}
console.log(`wrote ${written.length} modules under ${relative(repoRoot, familyDir)}/`);

// The docs' table always lists the whole table, whatever `--only` selected.
const docPath = join(tesseractDir, "docs", "languages.md");
const table = [
  "| Code | Language | Script |",
  "| --- | --- | --- |",
  ...JSON.parse(readFileSync(tablePath, "utf8")).map(
    (lang) => `| \`${lang.code}\` | ${lang.name} | ${lang.script} |`,
  ),
].join("\n");
const doc = readFileSync(docPath, "utf8");
const marked = /<!-- languages:start -->[\s\S]*<!-- languages:end -->/;
if (!marked.test(doc)) throw new Error(`${relative(repoRoot, docPath)} has no languages:start/end markers`);
writeFileSync(docPath, doc.replace(marked, `<!-- languages:start -->\n${table}\n<!-- languages:end -->`));

// One invocation for every module: a CLI start per module costs minutes over the table.
if (pin && written.length > 0) {
  execFileSync(
    "pnpm",
    ["run", "-s", "telo", "release", "stage", "--pin", ...written.flatMap((module) => ["--module", module])],
    { cwd: repoRoot, stdio: "inherit" },
  );
}
